{
  "root": "main_stack",
  "state": {
    "inventoryData": [
      {
        "item": "Laptop",
        "totalValue": 180000
      },
      {
        "item": "Monitor",
        "totalValue": 60000
      },
      {
        "item": "Keyboard",
        "totalValue": 37500
      },
      {
        "item": "Mouse",
        "totalValue": 15000
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_analysis",
        "intro_text",
        "item_value_breakdown_header",
        "chart_description_text",
        "inventory_table",
        "key_insight_title",
        "key_insight_text"
      ]
    },
    "title_analysis": {
      "type": "Text",
      "props": {
        "text": "Inventory Stock Value Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis calculates the potential total sales value for each item in your inventory, assuming all stock is sold at its current price. This data can be used to visualize item contributions to overall inventory value.",
        "variant": "body"
      },
      "children": []
    },
    "item_value_breakdown_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "graph_icon",
        "item_value_breakdown_title"
      ]
    },
    "graph_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000029_01_1_graph-up.svg"
      },
      "children": []
    },
    "item_value_breakdown_title": {
      "type": "Text",
      "props": {
        "text": "Item Potential Value Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "chart_description_text": {
      "type": "Text",
      "props": {
        "text": "The following table presents the calculated total value for each item, providing a breakdown of potential sales value.",
        "variant": "body"
      },
      "children": []
    },
    "inventory_table": {
      "type": "Table",
      "props": {
        "statePath": "/inventoryData",
        "columns": [
          {
            "key": "item",
            "label": "Item"
          },
          {
            "key": "totalValue",
            "label": "Total Value (USD)"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table",
        "primaryColumn": "item",
        "numericColumns": [
          "totalValue"
        ]
      },
      "children": []
    },
    "key_insight_title": {
      "type": "Text",
      "props": {
        "text": "Key Financial Insight",
        "variant": "h2"
      },
      "children": []
    },
    "key_insight_text": {
      "type": "Text",
      "props": {
        "text": "The Laptop has the highest potential total sales value, accounting for $180,000 if all units are sold.",
        "variant": "body"
      },
      "children": []
    }
  }
}
